parameters.jsCode:
const ZONA = 'America/Sao_Paulo';
const normalizar = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const servicos = $('Buscar Duração dos Serviços').all().map(i => i.json);

// Acha um serviço da planilha pelo nome: igual (ignorando acento/caixa) ou, se só um bater, parcial.
const encontrarServico = nome => {
  const alvo = normalizar(nome);
  if (!alvo) return null;
  const exato = servicos.find(s => normalizar(s.servico) === alvo);
  if (exato) return exato;
  const parciais = servicos.filter(s => normalizar(s.servico).includes(alvo) || alvo.includes(normalizar(s.servico)));
  return parciais.length === 1 ? parciais[0] : null;
};

// Duração em minutos pela planilha de Serviços; combinações ("X e Y") somam as partes.
const duracaoDoServico = nome => {
  if (!nome || normalizar(nome) === 'nao especificado') return null;
  const unico = encontrarServico(nome);
  if (unico) return Number(unico.duracao_minutos) || null;
  const partes = normalizar(nome).split(/\s*(?:\+|,| e )\s*/).filter(Boolean);
  if (partes.length < 2) return null;
  const encontrados = partes.map(encontrarServico);
  if (encontrados.some(s => !s || !Number(s.duracao_minutos))) return null;
  return encontrados.reduce((total, s) => total + Number(s.duracao_minutos), 0);
};

// A entrada são as linhas da planilha de Serviços; o agendamento em si vem pelo pareamento do item 0.
const output = { ...($('Classificar Resposta do Lembrete').first().json.output || {}) };
const agendamento = $('Processar Cada Agendamento').itemMatching(0).json;
const inicio = DateTime.fromISO(output.novo_horario_inicio, { zone: ZONA });
const duracao = duracaoDoServico(agendamento.servico);

// O término sai sempre de início + duração da planilha; o novo_horario_fim da IA só fica se o serviço não for achado.
if (duracao && inicio.isValid) {
  output.novo_horario_fim = inicio.plus({ minutes: duracao }).toFormat("yyyy-MM-dd'T'HH:mm:ssZZ");
}
const fim = DateTime.fromISO(output.novo_horario_fim, { zone: ZONA });

const abertura = 9 * 60;
const fechamento = 18 * 60;
const minutosInicio = inicio.hour * 60 + inicio.minute;
const minutosFim = fim.hour * 60 + fim.minute;
const domingo = inicio.weekday === 7;
const jaPassou = inicio.isValid && inicio < DateTime.now().setZone(ZONA);

const dentroDoExpediente =
  inicio.isValid &&
  fim.isValid &&
  !domingo &&
  !jaPassou &&
  minutosInicio >= abertura &&
  minutosInicio < fechamento &&
  minutosFim <= fechamento;

return [{
  json: { output, duracao_minutos: duracao, duracao_fonte: duracao ? 'planilha' : 'ia', dentro_do_expediente: dentroDoExpediente },
  pairedItem: { item: 0 }
}];

