SELECT google_event_id AS event_id, status, to_char(data_hora_inicio AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD"T"HH24:MI:SS') || '-03:00' AS data
FROM agendamentos
WHERE status IN ('agendado', 'remarcado');
